+// A request sees only records belonging to its site's locations. Objects and
+// appended records still belong to the underlying store, which saves in full.
+function siteStore(store, site) {
+  const locationIds = new Set(store.data.locations.filter((l) => l.site === site).map((l) => l.id));
+  const data = new Proxy(store.data, {
+    get(target, key) {
+      let predicate;
+      if (key === "locations") predicate = (l) => locationIds.has(l.id);
+      if (key === "batches" || key === "stocktakes" || key === "temperatures")
+        predicate = (record) => locationIds.has(record.location);
+      if (key === "movements") predicate = (m) => target.batches.some((b) => b.id === m.batchId && locationIds.has(b.location));
+      const original = target[key];
+      if (!predicate || !original) return original;
+      const view = original.filter(predicate);
+      Object.defineProperty(view, "push", { value: (...records) => original.push(...records) });
+      return view;
+    },
+  });
+  return { data, nextId: store.nextId.bind(store), save: store.save.bind(store) };
+}
